# -*- coding: utf-8 -*-
import json

W = "https://en.wiktionary.org/wiki/"

data = {
 "pdf_page": 415,
 "book_page": 385,
 "verified_by": "claude-opus-5",
 "verified_on": "2026-09-13",
 "entries": [
  {
   "entry": 0,
   "root": "Raika",
   "verdict": "plausible",
   "modern_form": "Old/Proto-Iranian *raika- (< *raiHka-) 'sand' — a reconstruction, not an attested Old Persian word; > MP rēg > NP rīg",
   "note": "The starred form is Hübschmann's: Pers. Studien p.68 no.642 'Np. rēg ‚Sand‘ = bal. rek = ap. *raika-'. Nourai's root box reproduces that reconstruction but prints it without the asterisk and labels it flatly 'Old Persian'; no such word is attested in the Old Persian inscriptions (Kent's lexicon has no word for 'sand'), so the label should read 'Old Iranian (reconstructed)'. The gloss 'sand, gravel' is right. Modern work (Korn, cited on Wiktionary; cf. Hasandust) takes MP rēg from a -ka- derivative of PIE *h₃reyH- 'to flow', i.e. *raiH-ka- 'that which flows/streams' — compatible with, and more explicit than, Nourai's *raika-. Horn p.142 also records the rival 19th-c. proposal (Bartholomae, ZDMG 46, 301 no. XIX) linking the Iranian words to Skt. sikatā- 'sand', which Hübschmann rejects ('gehört gewiss nicht zu skr. sikata-'); modern scholarship follows Hübschmann. The Rudakī line quoted in the box is from Bū-ye Jūy-e Mūliyān; the book prints «ریگ آموی و درشتی های او», where the received text reads «ریگ آموی و درشتیِ راهِ او» — a quotation variant, not an etymological problem.",
   "note_fa": "ریشهٔ این خانواده صورتِ بازساختهٔ *raika- (ایرانی باستان) است که نخست هوبشمان در «پژوهش‌های فارسی» (ص ۶۸، ذیل شمارهٔ ۶۴۲ هرن) پیشنهاد کرد: «فارسی نو rēg = بلوچی rēk = ایرانی باستان *raika-». این صورت در کتیبه‌های پارسی باستان گواهی نشده است، پس برچسبِ «پارسی باستان» در کتاب باید «ایرانی باستانِ بازسازی‌شده» خوانده شود؛ معنای «شن، ریگ» درست است. ریشه‌شناسی امروزی (کرن، به نقل ویکی‌واژه؛ نیز حسن‌دوست) آن را از *raiH-ka- از ریشهٔ هندواروپایی آغازین *h₃reyH- «روان شدن، جاری شدن» می‌گیرد که با پیشنهاد نورایی ناسازگار نیست. پیوند کهنِ بارتولومه با سنسکریت sikatā- «شن» را هوبشمان به‌صراحت رد کرده و پژوهش امروزی نیز آن را نپذیرفته است. کوتاه: ادعای نورایی با احتیاط پذیرفتنی است، به شرط آنکه ستاره (*) و عنوانِ درستِ زبان افزوده شود.",
